HOLIDAY_WORK.conversion:
// EA s.88(4) & PT Regs reg.6: extra day's basic pay for FT worked PH; pro-rated (PT_wk/FT_wk)*FT_day*hour_rate for PT.
const worked = get(ctx, 'work.days', []).filter((day) => {
	if (get(day, 'day_type', 'WORK') === 'REST') return false;
	const kind = get(day, 'holiday_kind', '');
	if (kind === '' || kind === 'MAKEUP_WORKDAY') return false;
	return Number(get(day, 'worked_hours', 0)) > 0;
});
if (worked.length === 0) return 0;
const emp = ctx.subject.employment;
if (get(emp, 'engagement', 'EMPLOYEE') === 'PART_TIME') {
	const ptWk = Number(get(emp, 'terms.normal_hours_per_week', 0));
	const ftWk = Number(get(emp, 'statutory_parameters.comparable_full_time_hours_per_week', 44));
	const ftDay = Number(get(emp, 'statutory_parameters.comparable_full_time_hours_per_day', 8));
	const phDayPay = ptWk > 0 && ftWk > 0 ? (ptWk / ftWk) * ftDay * ctx.hour_rate : ctx.day_rate;
	return worked.length * ctx.lookup.holiday_work_days * phDayPay;
}
return worked.length * ctx.lookup.holiday_work_days * ctx.day_rate;

