const rawRace = String(get(facts, 'race', ''))
	.trim()
	.toUpperCase()
	.split(' ')
	.filter((part) => part !== '')
	.join(' ');
const primaryRace = rawRace.split('-')[0].split('/')[0].trim();
const raceMatched =
	ctx.lookup.races.includes(rawRace) ||
	ctx.lookup.races.includes(rawRace.split('-').join(' ')) ||
