LQS_WAGE_FLOOR.effects:
const run = ctx.entry;
const from = run.salary_coverage.from;
const to = run.salary_coverage.to;
const contracts = get(ctx, 'reads.employment', []).filter((contract) => {
	if (contract.effective_range.from > to) return false;
	const end = get(contract, 'effective_range.to', null);
	return end == null || end >= from;
});
// MOM: the LQS binds firms that hold work passes
const holdsPasses = contracts.some((contract) =>
	ctx.lookup.work_pass_categories.includes(get(contract, 'terms.work_authorisation_category', ''))
);
if (!holdsPasses) return [];
return get(ctx, 'reads.payslip', []).flatMap((slip) => {
	const contract = contracts.find((row) => row.id === slip.employment_id);
	if (contract == null) return [];
	const terms = get(contract, 'terms', {});
	if (!ctx.lookup.local_residencies.includes(get(terms, 'residency_status', ''))) return [];
	if (get(contract, 'statutory_parameters.pwm_role', '') !== '') return [];
	// a month worked in part is no test of a monthly figure
	if (contract.effective_range.from > from) return [];
	const end = get(contract, 'effective_range.to', null);
	if (end != null && end < to) return [];
	const overtime = sum(
		get(slip, 'breakdown.lines', []).filter((line) => line.source === 'overtime_catalog').map((line) => line.amount)
	);
	const wage = Number(slip.ordinary_wages) - overtime;
	const hours = Number(get(terms, 'normal_hours_per_week', ctx.lookup.full_time_weekly_hours));
	// MOM: under 35 hours a week the LQS is hourly, on gross pay over the month's hours
	const floor =
		hours < ctx.lookup.full_time_minimum_hours
			? (ctx.lookup.hourly_floor * hours * ctx.lookup.weeks_per_year) / 12
			: ctx.lookup.monthly_floor;
	if (wage >= floor) return [];
	return [{
		entity_id: run.entity_id,
		employee_id: slip.employee_id,
		employment_id: slip.employment_id,
		title: ctx.lookup.title,
		due_on: to,
		occurrence_key: 'SG:LQS_WAGE_FLOOR:' + run.id + ':' + slip.employment_id
	}];
});

CPF_AW_YEAR_END_RECALCULATION.effects:
// CPF Act First Sch. & CPF Board Step 2: settle AW ceiling per employer at Dec or exit by summing each month's capped OW.
const run = ctx.entry;
const to = run.salary_coverage.to;
const yr = to.slice(0, 4);
const month = Number(to.slice(5, 7));
const contracts = get(ctx, 'reads.employment', []);
const balances = get(ctx, 'reads.employee_balance', []);
const scope = 'SG.' + run.entity_id;
return get(ctx, 'reads.payslip', []).flatMap((slip) => {
	if (!get(slip, 'breakdown.statutory', []).some((scheme) => scheme.code === 'CPF')) return [];
	const contract = contracts.find((row) => row.id === slip.employment_id);
	const leaving = String(get(contract, 'effective_range.to', ''));
	if (month !== 12 && (leaving === '' || leaving > month_end(to))) return [];
	const account = get(balances.find((row) => row.employee_id === slip.employee_id), 'account', {});
	const yearly = (code) => {
		const periods = get(account, 'pay.' + code, {});
		const kEmp = scope + '.Y.' + yr + '-01-01';
		const kJur = 'SG.Y.' + yr + '-01-01';
		const k = Object.hasOwn(periods, kEmp) ? kEmp : kJur;
		return Object.hasOwn(periods, k) ? Number(periods[k].total) : 0;
	};
	const ordinary = yearly('ORDINARY_WAGES');
	const additional = yearly('ADDITIONAL_WAGES') - ordinary;
	if (additional <= ctx.lookup.annual_ceiling - 12 * ctx.lookup.ordinary_ceiling) return [];
	const owPeriods = get(account, 'pay.ORDINARY_WAGES', {});
	const mPrefix = scope + '.M.' + yr + '-';
	const mPrefixLegacy = 'SG.M.' + yr + '-';
	const mKeys = Object.keys(owPeriods).filter((k) => k.startsWith(mPrefix) || k.startsWith(mPrefixLegacy));
	const started = String(get(contract, 'effective_range.from', ''));
	const opening = started.slice(0, 4) === yr ? Number(started.slice(5, 7)) : 1;
	const months = month - opening + 1;
	const cappedOw = mKeys.length > 0
		? mKeys.reduce((acc, k) => acc + Math.min(Number(get(owPeriods[k], 'total', 0)), ctx.lookup.ordinary_ceiling), 0)
		: Math.min(ordinary, ctx.lookup.ordinary_ceiling * months);
	if (month === 12 && ordinary === Number(slip.ordinary_wages) * months) return [];
	const ceiling = Math.max(0, ctx.lookup.annual_ceiling - cappedOw);
	return [{
		entity_id: run.entity_id,
		employee_id: slip.employee_id,
		employment_id: slip.employment_id,
		title: ctx.lookup.title + ': ceiling $' + ceiling.toFixed(2) + ', AW paid $' + additional.toFixed(2),
		due_on: add_days(month_end(to), ctx.lookup.offset_days),
		occurrence_key: 'SG:CPF_AW_YEAR_END_RECALCULATION:' + run.id + ':' + slip.employment_id
	}];
});

EP_SPASS_QUALIFYING_SALARY.condition:
// EFMA 1990 & MOM EP/S Pass eligibility: check monthly fixed salary against age-scaled statutory pass floor.
const emp = ctx.subject.employment;
if (get(emp, 'terms.residency_status', '') !== 'FOREIGNER') return false;
const pass = get(emp, 'terms.work_authorisation_category', '');
if (!['EMPLOYMENT_PASS', 'S_PASS'].includes(pass)) return false;
const from = String(ctx.entry.period).slice(0, 7) + '-01';
const to = month_end(from);
if (emp.effective_range.from > from) return false;
const leaving = get(emp.effective_range, 'to', null);
if (leaving != null && leaving < to) return false;
const fs = get(ctx.subject.employer, 'statutory_parameters.financial_services', false) === true;
const born = get(emp, 'payroll.date_of_birth', '');
const age = born !== '' ? age_on(born, to) : ctx.lookup.scale_start_age;
const frac = clamp((age - ctx.lookup.scale_start_age) / (ctx.lookup.scale_end_age - ctx.lookup.scale_start_age), 0, 1);
const minF = pass === 'EMPLOYMENT_PASS' ? (fs ? ctx.lookup.ep_fs_min : ctx.lookup.ep_general_min) : (fs ? ctx.lookup.spass_fs_min : ctx.lookup.spass_general_min);
const maxF = pass === 'EMPLOYMENT_PASS' ? (fs ? ctx.lookup.ep_fs_max : ctx.lookup.ep_general_max) : (fs ? ctx.lookup.spass_fs_max : ctx.lookup.spass_general_max);
const floor = minF + frac * (maxF - minF);
const lines = get(ctx.entry, 'breakdown.lines', []);
const ot = sum(lines.filter((l) => l.source === 'overtime_catalog').map((l) => l.amount));
