SICK_WITHIN_HOSPITALISATION.validate:
// EA 1968 s.89(1) & PT Regs reg.8: combined outpatient sick and hospitalisation leave cannot exceed the year's hospitalisation cap (pro-rated for PT).
const shared = ctx.reads.leave_catalog;
const item = shared.find((row) => row.code === ctx.entry.catalog_code);
if (item == null) return true;
const slots = get(ctx.entry, 'leave_catalog_entry_day', []);
if (slots.length === 0) return true;
const year = String(slots[0].incurred_on).slice(0, 4);
const isPt = get(ctx.subject.employment, 'engagement', 'EMPLOYEE') === 'PART_TIME';
const codes = isPt ? ['SICK_LEAVE_PART_TIME', 'HOSPITALIZATION_LEAVE_PART_TIME'] : ['SICK_LEAVE', 'HOSPITALIZATION_LEAVE'];
if (!codes.includes(ctx.entry.catalog_code)) return true;
const within = (held) => held.filter((slot) => String(slot.incurred_on).slice(0, 4) === year).length / 2;
const grouped = group_by(ctx.reads.leave_catalog_entry_day, 'leave_entry_id');
const taken = ctx.reads.leave_catalog_entry
	.filter((row) => codes.includes(row.catalog_code))
	.reduce((total, row) => total + within(get(grouped, row.id, [])), 0);
const wanted = within(slots);
const hospCode = isPt ? 'HOSPITALIZATION_LEAVE_PART_TIME' : ctx.lookup.hospitalisation;
const hospital = shared.find((row) => row.code === hospCode);
if (hospital == null) return true;
const months = calendar_completed_months(String(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from)), String(slots[0].incurred_on));
let cap = get(hospital.lookup, 'service_bands', []).filter((band) => band.service_months <= months).reduce((best, band) => Math.max(best, band.days), 0);
if (isPt) {
	const terms = get(ctx.subject.employment, 'terms', {});
	const facts = get(ctx.subject.employment, 'statutory_parameters', {});
	const weekly = Number(get(terms, 'normal_hours_per_week', 0));
	const day = Number(get(terms, 'normal_hours_per_day', 0)) || (Number(get(terms, 'normal_days_per_week', 0)) > 0 ? weekly / Number(terms.normal_days_per_week) : 0);
	const fullWeek = Number(get(facts, 'comparable_full_time_hours_per_week', 44));
	const fullDay = Number(get(facts, 'comparable_full_time_hours_per_day', 8));
	if (weekly > 0 && day > 0 && fullWeek > 0) cap = Math.ceil(((cap * fullDay * weekly) / fullWeek / day) * 2) / 2;
}
if (taken + wanted > cap) throw 'Sick and hospitalisation leave together would pass the ' + cap + ' days the year allows.';
return true;

YOUNG_PERSON_MINIMUM_AGE.validate:
// EA 1968 Part 8 s.68(1)-(2): prohibit employment under age 13 and industrial employment under age 15.
