if (born == null || get(ctx.entry, 'effective_range.from', null) == null) return true;
const years = age_on(String(born), String(ctx.entry.effective_range.from));
if (years < ctx.lookup.min_age) throw 'Employment Act s.68(1) prohibits employing a child below age 13.';
if (years < ctx.lookup.industrial_min_age && get(ctx.subject.employer, 'statutory_parameters.industrial_undertaking', false) === true)
	throw 'Employment Act s.68(2) prohibits employing a child below age 15 in an industrial undertaking.';
return true;

