lookup.entitlement:
// CDCSA s.12B & EA s.87A: 6d GPCL if youngest child is <7 during the year; else 2d ECL up to calendar year child turns 12 (age on Dec 31 <= 12).
const employment = ctx.subject.employment;
const yr = String(ctx.as_of).slice(0, 4);
const yearStart = yr + '-01-01';
const yearEnd = yr + '-12-31';
const children = get(employment, 'family', []).filter((m) => m.relation === 'CHILD' && get(m, 'born_on', null) != null && m.born_on <= ctx.as_of);
if (children.length === 0) return 0;
const minStartAge = Math.min(...children.map((m) => (m.born_on > yearStart ? 0 : age_on(m.born_on, yearStart))));
const minEndAge = Math.min(...children.map((m) => age_on(m.born_on, yearEnd)));
if (minEndAge > 12) return 0;
const start = get(employment, 'service_started_on', get(employment, 'effective_range.from', ctx.as_of));
const months = calendar_completed_months(start, ctx.as_of);
const bands = ctx.lookup.service_bands.filter((band) => band.service_months <= months);
if (bands.length === 0) return 0;
const full = minStartAge < ctx.lookup.child_age_limit_years ? 6 : 2;
return Math.min(full, Math.max(2, bands[bands.length - 1].days));

UNPAID_INFANT_CARE_LEAVE.eligibility:
// CDCSA 2001 s.12D: parent of citizen child under 2 with >=3 continuous months' service (12 unpaid days/year).
const employment = ctx.subject.employment;
const start = get(employment, 'service_started_on', get(employment, 'effective_range.from', ctx.as_of));
if (calendar_completed_months(start, ctx.as_of) < ctx.lookup.eligibility_months) return false;
const yearStart = String(ctx.as_of).slice(0, 4) + '-01-01';
return get(employment, 'family', []).some((member) =>
	member.relation === 'CHILD' &&
	get(member, 'born_on', null) != null &&
	member.born_on <= ctx.as_of &&
	(member.born_on > yearStart ? 0 : age_on(member.born_on, yearStart)) < ctx.lookup.child_age_limit_years
);

