const terms = ctx.subject.employment.terms;
const basic = ctx.month_wage;
if (get(terms, 'rate.unit', 'MONTHLY') !== 'MONTHLY' || !(basic > 0)) return ctx.day_rate * ctx.entry.quantity;
const allowance = get(terms, 'allowances.FIXED_MONTHLY.amount', 0);
const fixed = typeof allowance === 'number' ? allowance : get(allowance, 'value', 0);
return ctx.day_rate * ((basic + fixed) / basic) * ctx.entry.quantity;

lookup.entitlement:
// Employment (Part-Time Employees) Regulations reg.8(1): the similar full-time sick leave under EA s.89(1)(a),(2) in proportion to the part-timer's weekly hours; reg.2(2) deems that employee to work 8 hours a day and 44 hours a week.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const weekly = Number(get(terms, 'normal_hours_per_week', 0));
const stated = Number(get(terms, 'normal_hours_per_day', 0));
const daysPerWeek = Number(get(terms, 'normal_days_per_week', 0));
const day = stated > 0 ? stated : daysPerWeek > 0 ? weekly / daysPerWeek : 0;
if (!(weekly > 0) || !(day > 0)) return 0;
const start = get(employment, 'service_started_on', get(employment, 'effective_range.from', ctx.as_of));
const months = calendar_completed_months(start, ctx.as_of);
if (months < ctx.lookup.eligibility_months) return 0;
const at = ctx.lookup.service_bands.filter((band) => band.service_months <= months);
if (at.length === 0) return 0;
const full = at[at.length - 1].days;
// reg.2(2): the similar full-time employee's own hours; 8 a day and 44 a week only where there is none
const facts = get(employment, 'statutory_parameters', {});
const fullWeek = Number(get(facts, 'comparable_full_time_hours_per_week', ctx.lookup.full_time_weekly_hours));
const fullDay = Number(
	get(facts, 'comparable_full_time_hours_per_day', ctx.lookup.full_time_weekly_hours / ctx.lookup.full_time_days_per_week)
);
return Math.ceil(full * (weekly / fullWeek) * (fullDay / day) * 2) / 2;

SICK_LEAVE_PART_TIME.eligibility:
// Employment (Part-Time Employees) Regulations reg.8(1): eligibility gate.
return (
	get(ctx.subject.employment, 'engagement', 'EMPLOYEE') === 'PART_TIME' &&
	calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), ctx.as_of) >=
		ctx.lookup.eligibility_months
);

lookup.entitlement:
// Employment (Part-Time Employees) Regulations reg.8(1): the similar full-time hospitalisation leave under EA s.89(1)(b),(2) in proportion to the part-timer's weekly hours; reg.2(2) deems that employee to work 8 hours a day and 44 hours a week.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const weekly = Number(get(terms, 'normal_hours_per_week', 0));
const stated = Number(get(terms, 'normal_hours_per_day', 0));
const daysPerWeek = Number(get(terms, 'normal_days_per_week', 0));
const day = stated > 0 ? stated : daysPerWeek > 0 ? weekly / daysPerWeek : 0;
if (!(weekly > 0) || !(day > 0)) return 0;
const start = get(employment, 'service_started_on', get(employment, 'effective_range.from', ctx.as_of));
const months = calendar_completed_months(start, ctx.as_of);
if (months < ctx.lookup.eligibility_months) return 0;
const at = ctx.lookup.service_bands.filter((band) => band.service_months <= months);
if (at.length === 0) return 0;
const full = at[at.length - 1].days;
// reg.2(2): the similar full-time employee's own hours; 8 a day and 44 a week only where there is none
const facts = get(employment, 'statutory_parameters', {});
const fullWeek = Number(get(facts, 'comparable_full_time_hours_per_week', ctx.lookup.full_time_weekly_hours));
const fullDay = Number(
	get(facts, 'comparable_full_time_hours_per_day', ctx.lookup.full_time_weekly_hours / ctx.lookup.full_time_days_per_week)
);
return Math.ceil(full * (weekly / fullWeek) * (fullDay / day) * 2) / 2;

HOSPITALIZATION_LEAVE_PART_TIME.eligibility:
// Employment (Part-Time Employees) Regulations reg.8(1): eligibility gate.
return (
	get(ctx.subject.employment, 'engagement', 'EMPLOYEE') === 'PART_TIME' &&
	calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), ctx.as_of) >=
		ctx.lookup.eligibility_months
);

WORK_INJURY_MEDICAL_LEAVE.paid_share:
// WICA 2019 First Schedule para.4(1): full average monthly earnings for up to 14 days of outpatient medical leave, two-thirds from day 15, to one year from the accident.
if (ctx.event != null && calendar_completed_months(ctx.event.on, ctx.as_of) >= ctx.lookup.max_months) return 0;
return ctx.used < ctx.lookup.days ? 1 : 2 / 3;

WORK_INJURY_HOSPITALISATION_LEAVE.paid_share:
// WICA 2019 First Schedule para.4(1): full average monthly earnings for up to 60 days of hospitalisation leave, two-thirds from day 61, to one year from the accident.
if (ctx.event != null && calendar_completed_months(ctx.event.on, ctx.as_of) >= ctx.lookup.max_months) return 0;
return ctx.used < ctx.lookup.days ? 1 : 2 / 3;
